-- Validation Rules (T-DAI-079)
UPDATE normalized_fields SET validation_rules = '{"pattern": "^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$"}'::jsonb WHERE name = 'iban_vendor';
